import sys
from typing import Any, Dict

def execute_pipeline(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Execute validated business logic with structured error guarding."""
    if not isinstance(payload, dict):
        raise TypeError(f"Expected dict payload, got {type(payload).__name__}")

    processed = {k.strip().lower(): v for k, v in payload.items()}
    return {"status": "SUCCESS", "processed_keys": list(processed.keys()), "version": sys.version.split()[0]}

