# BINARY SEARCH & TWO-POINTER OPTIMIZATION
from typing import List, Optional

def binary_search(nums: List[int], target: int) -> Optional[int]:
    """Classic logarithmic search O(log n) time, O(1) auxiliary space."""
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return None

def two_sum_sorted(nums: List[int], target: int) -> Optional[tuple]:
    """Find 2 indices summing to target in a sorted list in O(n) time."""
    low, high = 0, len(nums) - 1
    while low < high:
        current_sum = nums[low] + nums[high]
        if current_sum == target:
            return (low, high)
        elif current_sum < target:
            low += 1
        else:
            high -= 1
    return None

sorted_arr = [2, 7, 11, 15, 23, 31, 45, 56, 89]
print("Index of 31 via Binary Search:", binary_search(sorted_arr, 31))
print("Pair indices summing to 38 via Two-Pointer:", two_sum_sorted(sorted_arr, 38))

# EXPECTED TERMINAL OUTPUT:
# Index of 31 via Binary Search: 5
# Pair indices summing to 38 via Two-Pointer: (1, 5)  (nums[1]=7 + nums[5]=31 = 38)

