# OBJECT-ORIENTED DOMAIN ARCHITECTURE WITH DATACLASSES & DUNDERS
from dataclasses import dataclass
from typing import List

@dataclass
class Account:
    account_number: str
    holder_name: str
    balance: float = 0.0

    def deposit(self, amount: float) -> float:
        if amount <= 0:
            raise ValueError("Deposit amount must be strictly positive.")
        self.balance += amount
        return self.balance

    def withdraw(self, amount: float) -> float:
        if amount > self.balance:
            raise ValueError(f"Insufficient funds: Balance is ${self.balance:.2f}")
        self.balance -= amount
        return self.balance

    def __str__(self) -> str:
        return f"Account({self.account_number}, Holder: {self.holder_name}, Balance: ${self.balance:,.2f})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Account):
            return NotImplemented
        return self.account_number == other.account_number

acc1 = Account("ACC-1001", "Ada Lovelace", 1500.0)
acc1.deposit(750.50)
acc1.withdraw(250.00)
print(acc1)

# EXPECTED TERMINAL OUTPUT:
# Account(ACC-1001, Holder: Ada Lovelace, Balance: $2,000.50)

